import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.Dkj3JE0_.js";const m=JSON.parse('{"title":"Plan JLPT N2","description":"","frontmatter":{"title":"Plan JLPT N2"},"headers":[],"relativePath":"fr/blogs/JLPT-N2/plan.md","filePath":"fr/blogs/JLPT-N2/plan.md"}'),i={name:"fr/blogs/JLPT-N2/plan.md"};function n(l,e,u,o,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="plan-d-apprentissage-du-jlpt-n2" tabindex="-1">Plan d’apprentissage du JLPT N2 <a class="header-anchor" href="#plan-d-apprentissage-du-jlpt-n2" aria-label="Permalink to &quot;Plan d’apprentissage du JLPT N2&quot;">​</a></h1><blockquote><p><strong>Hypothèse de travail :</strong> une préparation de 24 semaines et environ <strong>7 heures par semaine</strong>. Le plan vise à la fois l’examen et un japonais réellement utile ; la lecture et l’écoute restent donc liées à des documents authentiques.</p></blockquote><h2 id="criteres-d-achevement" tabindex="-1">Critères d’achèvement <a class="header-anchor" href="#criteres-d-achevement" aria-label="Permalink to &quot;Critères d’achèvement&quot;">​</a></h2><ul><li>Reconnaître le vocabulaire et les kanji essentiels du N2 en contexte, pas seulement sur des cartes mémoire.</li><li>Lire un texte de longueur N2 avec un objectif clair, une carte de sa structure et un rythme maîtrisé.</li><li>Suivre l’idée principale, la position de l’auteur et les détails importants en une seule écoute.</li><li>Réussir trois examens blancs chronométrés avec une marge au-dessus des seuils par section et du score total.</li></ul><h2 id="rythme-hebdomadaire" tabindex="-1">Rythme hebdomadaire <a class="header-anchor" href="#rythme-hebdomadaire" aria-label="Permalink to &quot;Rythme hebdomadaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fréquence</th><th style="text-align:right;">Durée</th><th>Travail</th></tr></thead><tbody><tr><td>Tous les jours</td><td style="text-align:right;">20 min</td><td>Révision espacée : vocabulaire, kanji et une phrase d’exemple lue à voix haute.</td></tr><tr><td>3 fois par semaine</td><td style="text-align:right;">35 min</td><td>Structure grammaticale → contraste avec une structure proche → 8 à 12 questions.</td></tr><tr><td>3 fois par semaine</td><td style="text-align:right;">30 min</td><td>Écoute active : anticiper, écouter une fois, résumer, puis vérifier avec la transcription.</td></tr><tr><td>2 fois par semaine</td><td style="text-align:right;">45 min</td><td>Lecture chronométrée suivie d’une analyse de la structure et des erreurs.</td></tr><tr><td>Week-end</td><td style="text-align:right;">90 min</td><td>Exercices mixtes par section et bilan de la semaine.</td></tr></tbody></table><h2 id="feuille-de-route-sur-24-semaines" tabindex="-1">Feuille de route sur 24 semaines <a class="header-anchor" href="#feuille-de-route-sur-24-semaines" aria-label="Permalink to &quot;Feuille de route sur 24 semaines&quot;">​</a></h2><h3 id="phase-1-—-point-de-depart-et-methode-semaines-1–2" tabindex="-1">Phase 1 — Point de départ et méthode (semaines 1–2) <a class="header-anchor" href="#phase-1-—-point-de-depart-et-methode-semaines-1–2" aria-label="Permalink to &quot;Phase 1 — Point de départ et méthode (semaines 1–2)&quot;">​</a></h3><ul><li>Faire un test d’essai chronométré couvrant les connaissances linguistiques, la lecture et l’écoute.</li><li>Classer les erreurs : vocabulaire, nuance grammaticale, enchaînement des phrases, vitesse de lecture, indice manqué ou attention.</li><li>Choisir un seul cours ou manuel principal par compétence. Les autres ressources vont sur une liste d’attente.</li><li>Lancer un paquet de révision fondé sur des phrases ; limiter les nouvelles cartes pour que la révision reste sous 25 minutes.</li></ul><h3 id="phase-2-—-couverture-semaines-3–12" tabindex="-1">Phase 2 — Couverture (semaines 3–12) <a class="header-anchor" href="#phase-2-—-couverture-semaines-3–12" aria-label="Permalink to &quot;Phase 2 — Couverture (semaines 3–12)&quot;">​</a></h3><ul><li>Apprendre 12 à 15 mots et 4 à 6 kanji par jour, six jours par semaine.</li><li>Apprendre 8 à 10 structures grammaticales par semaine, par groupes de contraste : cause, concession, restriction, tendance.</li><li>Lire chaque jour un court texte authentique : NHK, un essai, une page produit ou une note interne d’entreprise.</li><li>Écouter 15 à 20 minutes de japonais par jour ; trois jours par semaine, faire une réécoute intensive avec transcription.</li></ul><p>Chaque dimanche, rédiger un résumé de 150 à 250 caractères en utilisant deux structures de la semaine.</p><h3 id="phase-3-—-vitesse-et-integration-semaines-13–18" tabindex="-1">Phase 3 — Vitesse et intégration (semaines 13–18) <a class="header-anchor" href="#phase-3-—-vitesse-et-integration-semaines-13–18" aria-label="Permalink to &quot;Phase 3 — Vitesse et intégration (semaines 13–18)&quot;">​</a></h3><ul><li>Passer des questions isolées à des séries chronométrées de lecture et d’écoute.</li><li>En lecture, repérer la thèse de l’auteur, les mots d’opposition, les référents et le rôle de chaque paragraphe.</li><li>En écoute, anticiper le type de question et ne noter que les détails qui changent la réponse.</li><li>Faire du shadowing sur un extrait de 60 à 90 secondes trois fois par semaine, pour la reconnaissance des sons et le rythme.</li><li>Entretenir l’ancien vocabulaire ; réduire les nouvelles cartes si le taux de rappel passe sous 85 %.</li></ul><h3 id="phase-4-—-preparation-a-l-epreuve-semaines-19–23" tabindex="-1">Phase 4 — Préparation à l’épreuve (semaines 19–23) <a class="header-anchor" href="#phase-4-—-preparation-a-l-epreuve-semaines-19–23" aria-label="Permalink to &quot;Phase 4 — Préparation à l’épreuve (semaines 19–23)&quot;">​</a></h3><ul><li>Alterner chaque week-end tests par section et examens blancs complets.</li><li>Reproduire le minutage réel, les pauses, la diffusion audio et l’usage de la feuille de réponses.</li><li>Analyser pourquoi chaque distracteur est faux, surtout quand la bonne réponse a été devinée.</li><li>En semaine, travailler une seule sous-compétence faible à la fois.</li></ul><h3 id="phase-5-—-affutage-semaine-24" tabindex="-1">Phase 5 — Affûtage (semaine 24) <a class="header-anchor" href="#phase-5-—-affutage-semaine-24" aria-label="Permalink to &quot;Phase 5 — Affûtage (semaine 24)&quot;">​</a></h3><ul><li>Revoir les paires de grammaire souvent confondues, les lectures de kanji récurrentes et les mots-indices de l’écoute.</li><li>Faire de courtes séries chronométrées sans s’épuiser sur des tests complets.</li><li>Vérifier la logistique et protéger son sommeil.</li></ul><h2 id="bilan-mensuel-en-situation-reelle" tabindex="-1">Bilan mensuel en situation réelle <a class="header-anchor" href="#bilan-mensuel-en-situation-reelle" aria-label="Permalink to &quot;Bilan mensuel en situation réelle&quot;">​</a></h2><p>Toutes les quatre semaines :</p><ul><li>lire un article et en faire un résumé oral de deux minutes ;</li><li>tenir une conversation ou un échange linguistique de 20 minutes ;</li><li>écrire un court message professionnel et le faire corriger ;</li><li>noter ce que la préparation à l’examen améliore — et ce qu’elle n’améliore pas.</li></ul><h2 id="les-sept-premiers-jours" tabindex="-1">Les sept premiers jours <a class="header-anchor" href="#les-sept-premiers-jours" aria-label="Permalink to &quot;Les sept premiers jours&quot;">​</a></h2><ul><li>[ ] Passer le test d’essai et noter les scores par section.</li><li>[ ] Choisir une ressource principale par compétence.</li><li>[ ] Créer le paquet de révision et le carnet d’erreurs.</li><li>[ ] Enregistrer trois sources fiables de lecture et d’écoute.</li><li>[ ] Planifier le premier bloc mixte de 90 minutes.</li></ul>',23)])])}const h=a(i,[["render",n]]);export{m as __pageData,h as default};
